<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/geop_v8.php';
require_role(['TI','GESTOR','GESTOR_SINDICO','DIRETOR_EXECUTIVO','COORDENADOR_OPERACOES_OBRAS']);check_csrf();geop_v8_boot($pdo);
if (!geop_v8_feature_ready($pdo)) {
    if ((current_user()['perfil'] ?? '') === 'TI') redirect('atualizar_geop_v8');
    http_response_code(503); die('O módulo GEOP V8 aguarda a atualização do banco pelo TI.');
}
$mes=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['mes']??''))?$_GET['mes']:date('Y-m');$start=$mes.'-01 00:00:00';$end=date('Y-m-d H:i:s',strtotime($mes.'-01 +1 month'));$del=geop_v8_column_exists($pdo,'ordens_servico','excluida_em')?' AND os.excluida_em IS NULL':'';
$st=$pdo->prepare("SELECT COUNT(*) total,COALESCE(SUM(os.custo_materiais),0) materiais,COALESCE(SUM(os.custo_mao_obra),0) mao_obra,COALESCE(SUM(os.custo_terceiros),0) terceiros,COALESCE(SUM(os.custo_total_final),0) total_final,COALESCE(SUM(os.valor_previsto_orcamento),0) previsto FROM ordens_servico os WHERE os.criado_em>=? AND os.criado_em<? {$del}");$st->execute([$start,$end]);$k=$st->fetch(PDO::FETCH_ASSOC)?:[];
$cat=$pdo->prepare("SELECT COALESCE(c.nome,'Sem categoria') nome,COUNT(*) qtd,COALESCE(SUM(os.custo_total_final),0) custo FROM ordens_servico os LEFT JOIN categorias c ON c.id=os.categoria_id WHERE os.criado_em>=? AND os.criado_em<? {$del} GROUP BY c.id,c.nome ORDER BY custo DESC LIMIT 12");$cat->execute([$start,$end]);$cats=$cat->fetchAll(PDO::FETCH_ASSOC);
$loc=$pdo->prepare("SELECT COALESCE(l.nome,'Sem local') nome,COUNT(*) qtd,COALESCE(SUM(os.custo_total_final),0) custo FROM ordens_servico os LEFT JOIN locais l ON l.id=os.local_id WHERE os.criado_em>=? AND os.criado_em<? {$del} GROUP BY l.id,l.nome ORDER BY custo DESC LIMIT 12");$loc->execute([$start,$end]);$locs=$loc->fetchAll(PDO::FETCH_ASSOC);
$top=$pdo->prepare("SELECT os.id,os.numero_os,os.titulo,os.status,os.valor_previsto_orcamento,os.custo_materiais,os.custo_mao_obra,os.custo_terceiros,os.custo_total_final FROM ordens_servico os WHERE os.criado_em>=? AND os.criado_em<? {$del} ORDER BY os.custo_total_final DESC LIMIT 20");$top->execute([$start,$end]);$tops=$top->fetchAll(PDO::FETCH_ASSOC);
$trend=$pdo->query("SELECT DATE_FORMAT(criado_em,'%Y-%m') mes,COUNT(*) qtd,COALESCE(SUM(custo_total_final),0) custo FROM ordens_servico WHERE criado_em>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(criado_em,'%Y-%m') ORDER BY mes")->fetchAll(PDO::FETCH_ASSOC);
render_header('Dashboard financeiro');
?>
<div class="d-flex justify-content-between align-items-end flex-wrap gap-2 mb-3"><div><h1 class="h3 mb-1">Dashboard financeiro das OS</h1><p class="text-muted mb-0">Custos consolidados, orçamento e concentração por categoria/local.</p></div><form method="get" class="d-flex gap-2"><input class="form-control" type="month" name="mes" value="<?=e($mes)?>"><button class="btn btn-primary">Filtrar</button></form></div>
<div class="row g-3 mb-3"><?php foreach([['OS no mês',$k['total']??0,''],['Materiais',$k['materiais']??0,'R$'],['Mão de obra',$k['mao_obra']??0,'R$'],['Terceiros',$k['terceiros']??0,'R$'],['Custo final',$k['total_final']??0,'R$'],['Orçamento previsto',$k['previsto']??0,'R$']] as [$label,$val,$prefix]):?><div class="col-6 col-lg-2"><div class="card h-100"><div class="card-body"><div class="small text-muted"><?=e($label)?></div><div class="fs-5 fw-bold"><?= $prefix?e($prefix.' '.number_format((float)$val,2,',','.')):e((string)$val)?></div></div></div></div><?php endforeach?></div>
<div class="row g-3 mb-3"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Por categoria</h2><table class="table table-sm"><thead><tr><th>Categoria</th><th>OS</th><th class="text-end">Custo</th></tr></thead><tbody><?php foreach($cats as $r):?><tr><td><?=e($r['nome'])?></td><td><?=e((string)$r['qtd'])?></td><td class="text-end">R$ <?=e(number_format((float)$r['custo'],2,',','.'))?></td></tr><?php endforeach?></tbody></table></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Por local</h2><table class="table table-sm"><thead><tr><th>Local</th><th>OS</th><th class="text-end">Custo</th></tr></thead><tbody><?php foreach($locs as $r):?><tr><td><?=e($r['nome'])?></td><td><?=e((string)$r['qtd'])?></td><td class="text-end">R$ <?=e(number_format((float)$r['custo'],2,',','.'))?></td></tr><?php endforeach?></tbody></table></div></div></div></div>
<div class="card mb-3"><div class="card-body"><h2 class="h5">Evolução — últimos 12 meses</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Mês</th><th>OS</th><th>Custo</th></tr></thead><tbody><?php foreach($trend as $r):?><tr><td><?=e($r['mes'])?></td><td><?=e((string)$r['qtd'])?></td><td>R$ <?=e(number_format((float)$r['custo'],2,',','.'))?></td></tr><?php endforeach?></tbody></table></div></div></div>
<div class="card"><div class="card-body"><h2 class="h5">OS de maior custo</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>OS</th><th>Título</th><th>Status</th><th>Previsto</th><th>Real</th><th>Variação</th></tr></thead><tbody><?php foreach($tops as $r):$prev=(float)($r['valor_previsto_orcamento']??0);$real=(float)$r['custo_total_final'];?><tr><td><a href="<?=e(app_path('ordem_detalhe',['id'=>$r['id']]))?>"><?=e($r['numero_os'])?></a></td><td><?=e($r['titulo'])?></td><td><?=e($r['status'])?></td><td>R$ <?=e(number_format($prev,2,',','.'))?></td><td>R$ <?=e(number_format($real,2,',','.'))?></td><td><?= $prev>0?e(number_format($real-$prev,2,',','.')):'-'?></td></tr><?php endforeach?></tbody></table></div></div></div>
<?php render_footer(); ?>
